params.code:
const searchTerm = "กระเบื้อง";

// Search in products
const products = query_pg(`
  SELECT itemcode, barcode, name0, unitcode, price1, price_retail, brandnames, categorynames
  FROM productbarcode
  WHERE name0 ILIKE '%${searchTerm}%' 
  OR brandnames ILIKE '%${searchTerm}%'
  OR categorynames ILIKE '%${searchTerm}%'
  LIMIT 10
`);

// Search in debtors (customers)
const debtors = query_pg(`
  SELECT code, taxid, names
  FROM debtor
  WHERE names::text ILIKE '%${searchTerm}%'
  LIMIT 10
`);

// Search in creditors (suppliers)
const creditors = query_pg(`
  SELECT code, taxid, names
  FROM creditor
  WHERE names::text ILIKE '%${searchTerm}%'
  LIMIT 10
`);

return {
  products: products,
  debtors: debtors,
  creditors: creditors
};
